for s, k2 in (("verse", 2), ("chorus", 2), ("chorus", "last")):
    o = {}
    for body in ("bb", "rs", "build"):
        R = [pair(wins[(b, p, (s, 1))], wins[k]) for k in wins for b, p, w in [k] if b == body and w == (s, k2) and (b, p, (s, 1)) in wins and len(wins[k]) >= 12 and len(wins[(b, p, (s, 1))]) >= 12]
        R = pd.DataFrame(R); o[body] = {"pairs": len(R), **{c: [round(float(R[c].mean()), 3), round(float(R[c].quantile(.25)), 3), round(float(R[c].quantile(.75)), 3)] for c in R.columns}, "bars all the same rhythm": round(float((R.bars_same_rhythm == 1).mean()), 3), "no bar the same rhythm": round(float((R.bars_same_rhythm == 0).mean()), 3)}
    rel[f"{s} {k2} beside {s} 1"] = o
out["B4. the later window beside the first (mean, 25th, 75th)"] = rel
json.dump(out, open("whole_findings.json", "w"), indent=1); print(json.dumps(out, indent=1))
